def add(refs,key,title,stem,opts,why,wrong,typ='conceptual',difficulty='easy',assumptions=None,steps=None,forms=None,conflict=None):
 q=b.add([r[0] for r in refs],key,title,stem,opts,0,why,[why]+wrong,typ=typ,difficulty=difficulty,assumptions=assumptions,steps=steps,formulas=forms,conflict=conflict)
 for c,r in zip(q['citations'],refs):c.update(kind=r[1],locator=f'Lecture L59, physical PDF page {r[0]}, printed footer {r[0]-1876}: {r[2]}',role=r[3] if len(r)>3 else ('premise' if typ in ('numerical','derivation','scenario') else 'explicit'))
 if conflict:q['conflictResolution'].update(sourceId='lectures',sourceSha256=SHA,physicalPages=[r[0] for r in refs if len(r)>3 and r[3]=='conflict'])
 q['difficultyRationale']={'easy':'Direct source distinction, diagram reading or single stated relation.','medium':'Applies source relations under explicitly supplied additional conditions or combines multiple stages.','hard':'Integrates several calculations and frame/model constraints rather than direct recognition.'}[difficulty]
 return q
DREF=(1883,'equation','Motion equations v=r(omega_R+omega_L)/2 and omega=r(omega_R-omega_L)/L; r and full wheel separation L definitions.')
DF=formula('v=r(ωR+ωL)/2; ω=r(ωR−ωL)/L',{'v':'body forward velocity at the wheel-axis midpoint','ω':'body yaw rate, positive for right wheel faster than left','ωR,ωL':'right and left wheel angular velocities with positive forward rolling','r':'common wheel radius','L':'full lateral distance between driven wheels'},{'v':'m/s','ω,ωR,ωL':'rad/s','r,L':'m'},['Equal positive wheel radii, L>0, rigid planar differential drive, pure rolling/no lateral slip; radians used.'])
add([(1880,'table','Traditional/AI comparison, particularly integration of YOLOv8n with classical robotics.')],'hybrid','Hybrid AI and classical control','Which description best matches this robot’s architecture rather than treating AI as a replacement for every classical component?',['Learned object perception is combined with model-based kinematics, localization/planning and PID motor control.','Learned object perception directly replaces wheel kinematics and encoder speed feedback.','Classical PID itself learns the image object categories used by YOLOv8n.','Adding object detection makes map-based localization unnecessary.'],'The source explicitly combines AI-based perception with classical robotics methods, rather than replacing all of them.',['The source retains classical kinematics and feedback.','PID regulates motion error; the detector supplies object categories.','Semantic detection and robot localization serve different purposes.'])
add([(1881,'statement','AMR definition and five named characteristics.')],'amr','AMR autonomy','Which situation best matches the source definition of an autonomous mobile robot?',['A robot senses its surroundings and makes navigation decisions without continuous human steering.','A powered platform moves only while an operator continuously sends every steering command.','A fixed-base camera detects objects but cannot navigate its platform.','A mobile base repeats fixed timed commands without sensing its surroundings.'],'The definition requires sensing, decisions and navigation without continuous human intervention.',['Continuous teleoperation does not meet the stated autonomy condition.','Perception alone does not provide mobile navigation.','Open-loop timed motion lacks the stated environmental sensing and decision process.'])
add([(1881,'statement','Key Characteristics: perception, localization, planning, navigation and decision making.')],'roles','AMR functional roles','Which assignment correctly separates localization from planning?',['Localization estimates where the robot is; planning selects a route toward the goal.','Localization selects the route; planning estimates the current pose.','Localization converts PWM to motor current; planning measures wheel pulses.','Localization labels object classes; planning estimates camera colour.'],'Localization estimates current position; planning determines a suitable path.',['This reverses the two functions.','These are low-level drive/sensing roles, not the requested pair.','These are perception/image functions, not localization and path selection.'])
add([(1882,'figure','Front/side platform sketches labelled Driven wheels and Caster wheel.')],'caster','Driven wheels and passive caster','In the source sketches, what is the passive caster’s role?',['Support the platform while the two independently driven wheels generate the commanded differential motion.','Act as a third independently controlled differential-drive wheel.','Measure heading in place of the two wheel encoders.','Steer the body by a commanded caster steering angle shown in the diagram.'],'The source identifies a passive supporting caster and two independently driven wheels.',['A third driven wheel is not shown.','A caster is not the wheel-rotation measurement system.','No commanded caster steering actuator is shown.'],typ='diagram')
add([DREF],'rates','Wheel and body rates','Which symbol interpretation is consistent with the printed motion equations?',['ωR and ωL are wheel angular rates; ω is body yaw rate; L is the full driven-wheel separation.','ωR and ωL are wheel linear speeds; ω is body yaw rate; L is full separation.','ωR and ωL are wheel angular rates; ω is body yaw rate; L is half the separation.','ωR and ωL are wheel angular rates; ω is the average wheel rate and v is yaw rate.'],'The input/output labels and definitions distinguish wheel angular speeds from body velocities and define L as the distance between wheels.',['The radius conversion would be incorrect if the wheel terms were already linear speeds.','The source L is full separation, not half track width.','The output labels identify v as linear velocity and ω as angular velocity.'],forms=[DF])
add([DREF],'forward','Differential-drive numerical motion','Added ideal example: r=0.10 m, L=0.50 m, ωR=6 rad/s and ωL=2 rad/s. What are (v,ω)?',['(0.40 m/s, 0.80 rad/s).','(0.80 m/s, 0.40 rad/s).','(0.40 m/s, −0.80 rad/s).','(0.20 m/s, 0.80 rad/s).'],'v=0.10(6+2)/2=0.40 m/s and ω=0.10(6−2)/0.50=0.80 rad/s.',['This confuses the sum and difference scalings.','The printed sign is right minus left.','This halves the already averaged linear speed again.'],typ='numerical',difficulty='medium',assumptions=['Added values; ideal equal-radius no-slip model.'],steps=['Average wheel rates, then multiply by radius.','Multiply the right-minus-left difference by r/L.'],forms=[DF])
add([(1882,'statement','Opposite wheel directions → in-place rotation bullet.','conflict'),DREF],'opposite','Condition for pure rotation','The source shorthand says opposite wheel directions give in-place rotation. Under its ideal equations, which added case actually gives zero translation?',['ωR=+4 rad/s and ωL=−4 rad/s, with equal wheel radii.','ωR=+4 rad/s and ωL=−2 rad/s, with equal wheel radii.','ωR=+4 rad/s and ωL=+4 rad/s, with equal wheel radii.','ωR=0 and ωL=+4 rad/s, with equal wheel radii.'],'Zero midpoint translation requires ωR+ωL=0, so the opposite rates must have equal magnitudes for equal radii.',['Opposite signs alone leave a nonzero sum and therefore translation.','Equal signed rates give straight translation rather than pure rotation.','One stationary wheel produces rotation about that wheel, not the midpoint.'],assumptions=['Equal radii and ideal rolling. The printed shorthand is explicitly qualified by v=0.'],forms=[DF],conflict='p1882 says opposite wheel directions imply in-place rotation without stating equal magnitudes. p1883 requires a zero sum for zero translation.')
IF=formula('ωR=(v+Lω/2)/r; ωL=(v−Lω/2)/r',{'ωR,ωL':'right and left wheel angular velocity commands','v':'desired body forward velocity','ω':'desired yaw rate','L':'full wheel separation','r':'common radius'},{'ωR,ωL,ω':'rad/s','v':'m/s','L,r':'m'},['Derived algebraically from the printed forward equations; r>0, L>0; ideal equal-radius rolling.'])
add([DREF],'inverse','Inverse wheel commands','Added command: v=0.30 m/s, ω=1 rad/s, r=0.10 m, L=0.40 m. Which wheel rates implement it under the printed model?',['ωR=5 rad/s, ωL=1 rad/s.','ωR=1 rad/s, ωL=5 rad/s.','ωR=7 rad/s, ωL=−1 rad/s.','ωR=3 rad/s, ωL=3 rad/s.'],'The half-track yaw contribution is Lω/2=0.20 m/s; divide 0.30±0.20 by r to obtain 5 and 1 rad/s.',['This reverses the commanded yaw sign.','This uses the full Lω instead of half.','Equal wheel rates omit the requested yaw.'],typ='numerical',difficulty='medium',assumptions=['Added numerical command; no slip and no actuator saturation.'],steps=['Solve the sum/difference equations.','Compute ωR=(0.30+0.20)/0.10 and ωL=(0.30−0.20)/0.10.'],forms=[DF,IF])
add([DREF],'curvature','Turning radius','For a no-slip differential drive with v=0.40 m/s and ω=0.80 rad/s, what is the radius of the midpoint’s circular path while these rates remain constant?',['0.50 m.','2.00 m.','0.32 m.','0.20 m.'],'For nonzero constant yaw rate, radius is v/ω=0.50 m.',['This takes the reciprocal ratio and has the wrong dimensions.','This multiplies v and ω rather than dividing.','This halves the forward velocity without the required ratio.'],typ='numerical',difficulty='easy',assumptions=['Added constant body rates; planar no-slip motion, ω≠0.'],steps=['Use the circular-motion relation v=ρω.','Compute ρ=0.40/0.80.'],forms=[formula('ρ=v/ω',{'ρ':'signed turning radius of the wheel-axis midpoint','v':'forward body speed','ω':'body yaw rate'},{'ρ':'m','v':'m/s','ω':'rad/s'},['Constant planar body rates; ω≠0 and radians.'])])
add([(1884,'statement','Jetson high-level processing, Arduino real-time motor control and ROS2 software stack.')],'compute','High-level and low-level split','Which pairing matches the reported demonstration hardware?',['Jetson Orin Nano: high-level processing; Arduino Mega2560: low-level motor control.','Arduino Mega2560: YOLOv8n inference; Jetson Orin Nano: passive wheel support.','RPLidar: low-level PWM generation; Arduino: depth imaging.','RealSense D435i: global path server; Jetson: wheel-rotation transducer.'],'The source assigns high-level computation to Jetson and motor control to Arduino.',['This swaps computation roles and assigns mechanical support to a computer.','LiDAR scans and the Arduino does not replace a depth camera.','The camera and encoder are sensors, distinct from the planning computer.'])
add([(1884,'statement','Software stack lists SLAM Toolbox, AMCL, Nav2, robot_localization(EKF), YOLOv8n.')],'stack','Named software roles','Which complete mapping is consistent with the reported software stack?',['SLAM Toolbox: mapping; AMCL: localization in a saved map; Nav2: navigation; YOLOv8n: object perception.','SLAM Toolbox: motor PWM; AMCL: depth registration; Nav2: object labels; YOLOv8n: wheel odometry.','SLAM Toolbox: object labels; AMCL: map-free wheel control; Nav2: battery management; YOLOv8n: TF storage.','SLAM Toolbox: saved-image display; AMCL: global path search; Nav2: encoder pulse counting; YOLOv8n: map saving.'],'The named packages have complementary mapping, localization, navigation and perception roles.',['This assigns sensor and drive tasks to unrelated packages.','The listed roles do not match the reported system.','Display, path planning and encoder tasks are misassigned.'])
add([(1885,'figure','Motor Control column: Velocity Command → Arduino controller → motor drivers → drive motors.')],'motor-chain','Motor execution chain','Which sequence follows the motor-control column of the system architecture?',['Velocity command → Arduino motor controller → motor drivers → drive motors.','Velocity command → motor drivers → AMCL → drive motors.','Encoder pulses → YOLOv8 → battery → drive motors.','Global map → drive motors → motor drivers → Arduino controller.'],'The diagram separates high-level velocity requests, low-level control, drive electronics and motors.',['AMCL is localization, not the motor-drive stage.','Detection and battery are not that control chain.','This reverses the motor execution direction.'],typ='diagram')
